   "rationale": "Adds a hook verb that parses the public payload (plain text or JSON object with msg and sig), verifies msg against the attached ssh-keygen -Y signature in namespace mshkn using Mike's pinned ed25519 public key, and prints \"mike\" on success. The hook's stdout becomes the rest of the principal name, yielding principal mshkn:mike. Unsigned, malformed, or invalid signatures print nothing (no identity). Pinned key: ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIGBOx5qhuCa7F5+H2+67PuEm90BFkfiSZ6KLH8nwAJ9K",
   "recipe_id": "rcp-ae1511681c0e",
   "status": "ready",
   "supersedes": null,
   "title": "verb verify_mike: pre-turn hook asserting mshkn:mike via ssh-keygen signature",
   "verb": {
    "allow": [],
    "asserts": "mshkn",
    "chain": "verb/verify_mike",
    "description": "Verify Mike's ssh-keygen -Y signature (namespace mshkn) over msg and print 'mike' to assert identity mshkn:mike.",
    "dockerfile": "FROM mshkn-base\nRUN mkdir -p /verb && printf '%s\\n' '#!/usr/bin/env perl' 'use strict;' 'use warnings;' '' 'my $PUBKEY = \"ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIGBOx5qhuCa7F5+H2+67PuEm90BFkfiSZ6KLH8nwAJ9K\";' 'my $NL = chr(10);' 'my $DQ = chr(34);' 'my $BS = chr(92);' 'my $OB = chr(123);' 'my $CB = chr(125);' 'my $CO = chr(58);' 'my $CM = chr(44);' 'my $POS = 0;' '' 'sub tmpdir {' '    my $d = `mktemp -d 2>/dev/null`;' '    $d = substr($d, 0, length($d) - 1) if substr($d, -1) eq chr(10);' '    return $d;' '}' '' 'sub is_ws {' '    my ($o) = @_;' '    return 1 if $o == 32 || $o == 9 || $o == 10 || $o == 13;' '    return 0;' '}' '' 'sub parse_json_string {' '    my ($s) = @_;' '    my $len = length($s);' '    return undef if $POS >= $len || ord(substr($s, $POS, 1)) != 34;' '    $POS++;' '    my $out = \"\";' '    while ($POS < $len) {' '        my $o = ord(substr($s, $POS, 1));' '        if ($o == 34) { $POS++; return $out; }' '        if ($o == 92) {' '            $POS++;' '            return undef if $POS >= $len;' '            my $e = ord(substr($s, $POS, 1));' '            $POS++;' '            if ($e == 110) { $out .= chr(10); }' '            elsif ($e == 116) { $out .= chr(9); }' '            elsif ($e == 114) { $out .= chr(13); }' '            elsif ($e == 98) { $out .= chr(8); }' '            elsif ($e == 102) { $out .= chr(12); }' '            elsif ($e == 117) {' '                return undef if $POS + 4 > $len;' '                my $hex = substr($s, $POS, 4);' '                $POS += 4;' '                $out .= chr(hex($hex));' '            }' '            else { $out .= chr($e); }' '        } else {' '            $out .= chr($o);' '            $POS++;' '        }' '    }' '    return undef;' '}' '' 'sub skip_value {' '    my ($s) = @_;' '    my $len = length($s);' '    while ($POS < $len && is_ws(ord(substr($s, $POS, 1)))) { $POS++; }' '    return undef if $POS >= $len;' '    my $o = ord(substr($s, $POS, 1));' '    if ($o == 34) {' '        my $v = parse_json_string($s);' '        return $v;' '    }' '    if ($o == 123 || $o == 91) {' '        my $open = $o;' '        my $close = ($o == 123) ? 125 : 93;' '        my $depth = 0;' '        my $instr = 0;' '        my $esc = 0;' '        while ($POS < $len) {' '            my $c = ord(substr($s, $POS, 1));' '            if ($instr) {' '                if ($esc) { $esc = 0; }' '                elsif ($c == 92) { $esc = 1; }' '                elsif ($c == 34) { $instr = 0; }' '            } else {' '                if ($c == 34) { $instr = 1; }' '                elsif ($c == $open) { $depth++; }' '                elsif ($c == $close) { $depth--; last if $depth == 0; }' '            }' '            $POS++;' '        }' '        $POS++ if $POS < $len;' '        return undef;' '    }' '    while ($POS < $len) {' '        my $c = ord(substr($s, $POS, 1));' '        last if $c == 44 || $c == 125 || $c == 93 || is_ws($c);' '        $POS++;' '    }' '    return undef;' '}' '' 'sub parse_payload {' '    my ($text) = @_;' '    return undef unless defined($text);' '    my $len = length($text);' '    $POS = 0;' '    while ($POS < $len && is_ws(ord(substr($text, $POS, 1)))) { $POS++; }' '    return undef if $POS >= $len || ord(substr($text, $POS, 1)) != 123;' '    $POS++;' '    my %obj;' '    while (1) {' '        while ($POS < $len && is_ws(ord(substr($text, $POS, 1)))) { $POS++; }' '        return undef if $POS >= $len;' '        my $o = ord(substr($text, $POS, 1));' '        last if $o == 125;' '        return undef if $o != 34;' '        my $key = parse_json_string($text);' '        return undef unless defined($key);' '        while ($POS < $len && is_ws(ord(substr($text, $POS, 1)))) { $POS++; }' '        return undef if $POS >= $len || ord(substr($text, $POS, 1)) != 58;' '        $POS++;' '        my $val = skip_value($text);' '        $obj{$key} = $val if defined($val);' '        while ($POS < $len && is_ws(ord(substr($text, $POS, 1)))) { $POS++; }' '        return undef if $POS >= $len;' '        my $sep = ord(substr($text, $POS, 1));' '        if ($sep == 44) { $POS++; next; }' '        last if $sep == 125;' '        return undef;' '    }' '    return undef unless exists $obj{msg} && exists $obj{sig};' '    return undef unless defined($obj{msg}) && defined($obj{sig});' '    return ($obj{msg}, $obj{sig});' '}' '' 'sub json_escape {' '    my ($s) = @_;' '    my $out = \"\";' '    for my $i (0 .. length($s) - 1) {' '        my $c = substr($s, $i, 1);' '        my $o = ord($c);' '        if ($o == 34) { $out .= $BS . $DQ; }' '        elsif ($o == 92) { $out .= $BS . $BS; }' '        elsif ($o == 10) { $out .= $BS . chr(110); }' '        elsif ($o == 13) { $out .= $BS . chr(114); }' '        elsif ($o == 9) { $out .= $BS . chr(116); }' '        else { $out .= $c; }' '    }' '    return $out;' '}' '' 'sub verify {' '    my ($payload, $pubkey) = @_;' '    $pubkey = $PUBKEY unless defined($pubkey) && $pubkey ne \"\";' '    my ($msg, $sig) = parse_payload($payload);' '    return undef unless defined($msg) && defined($sig);' '    my $d = tmpdir();' '    return undef if $d eq \"\";' '    my $allowed = $d . \"/allowed_signers\";' '    my $sigfile = $d . \"/msg.sig\";' '    open(my $fa, \">\", $allowed) or return undef;' '    print $fa \"mike namespaces=\" . $DQ . \"mshkn\" . $DQ . \" \" . $pubkey . $NL;' '    close $fa;' '    open(my $fs, \">\", $sigfile) or return undef;' '    print $fs $sig;' '    close $fs;' '    my @candidates = ($msg);' '    my $ends_nl = (substr($msg, -1) eq $NL);' '    push @candidates, ($msg . $NL) unless $ends_nl;' '    for my $cand (@candidates) {' '        my $msgfile = $d . \"/msg\";' '        open(my $fm, \">\", $msgfile) or next;' '        print $fm $cand;' '        close $fm;' '        system(\"ssh-keygen -Y verify -f $allowed -I mike -n mshkn -s $sigfile < $msgfile >/dev/null 2>&1\");' '        return \"mike\" if $? == 0;' '    }' '    return undef;' '}' '' 'sub selftest {' '    my $d = tmpdir();' '    if ($d eq \"\") { print STDERR \"SELFTEST_FAIL_TMP\" . $NL; return 1; }' '    my $key = $d . \"/key\";' '    my $msgfile = $d . \"/msg\";' '    open(my $fm, \">\", $msgfile) or do { print STDERR \"SELFTEST_FAIL_WRITE\" . $NL; return 1; };' '    print $fm \"hello\";' '    close $fm;' '    my $QQ = $DQ . $DQ;' '    system(\"ssh-keygen -t ed25519 -f $key -N $QQ -q >/dev/null 2>&1\");' '    if ($? != 0) { print STDERR \"SELFTEST_FAIL_KEYGEN\" . $NL; return 1; }' '    system(\"ssh-keygen -Y sign -f $key -n mshkn $msgfile >/dev/null 2>&1\");' '    if ($? != 0) { print STDERR \"SELFTEST_FAIL_SIGN\" . $NL; return 1; }' '    my $pub = `ssh-keygen -y -f $key 2>/dev/null`;' '    my @p = split(\" \", $pub);' '    $pub = $p[0] . \" \" . $p[1];' '    open(my $fsig, \"<\", $msgfile . \".sig\") or do { print STDERR \"SELFTEST_FAIL_SIGREAD\" . $NL; return 1; };' '    local $/;' '    my $sig = <$fsig>;' '    close $fsig;' '    my $payload = $OB . $DQ . \"msg\" . $DQ . $CO . $DQ . \"hello\" . $DQ . $CM . $DQ . \"sig\" . $DQ . $CO . $DQ . json_escape($sig) . $DQ . $CB;' '    my $ident = verify($payload, $pub);' '    if (defined($ident) && $ident eq \"mike\") {' '        print STDERR \"SELFTEST_OK\" . $NL;' '        return 0;' '    }' '    print STDERR \"SELFTEST_FAIL_VERIFY\" . $NL;' '    return 1;' '}' '' 'my $arg = @ARGV ? shift(@ARGV) : \"\";' 'if ($arg eq \"SELFTEST\") { exit selftest(); }' 'my $ident = verify($arg);' 'if (defined($ident)) { print $ident; }' 'exit 0;' > /verb/verify.pl",
